using Htt.Infrastructure;
using Htt.SharedKernel;
using Htt.Host.Api.MasterData;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.Accounting;
public sealed record BasPeriodInput(string Reference,DateOnly From,DateOnly To,string Cadence,string GstBasis,string ReportingMethod,bool RegistrationConfirmed,DateOnly? DueOn=null,string CalculationMethod="ACCOUNTS");
public sealed record BasActionInput(string Reference,string Reason,DateOnly? LodgedOn=null);
public sealed record BasMethodInput(string ReportingMethod,string CalculationMethod,string Reason);
public sealed record BasClassificationInput(string SalesClass,string PurchaseClass,decimal? InputTaxedPercent,string Reason);
internal static class BasEndpoints
{
 private static long Version(HttpContext h){if(!long.TryParse(h.Request.Headers.IfMatch.ToString().Trim('"'),out var v)||v<1)throw new BusinessException("version_required","Current If-Match required.",428);return v;}
 private static async Task<IResult> Query(CompanySession s,string sql,CancellationToken ct,params DbArg[] args)=>Results.Content((string)(await One(s,sql,ct,args))["result"]!,"application/json");
 private static Task<Dictionary<string,object?>> Period(CompanySession s,Guid id,CancellationToken ct)=>One(s,"SELECT p.*,k.state,k.version,k.current_snapshot_id FROM accounting.bas_effective_periods p JOIN accounting.bas_period_controls k ON k.company_id=p.company_id AND k.id=p.id WHERE p.company_id=@company AND p.id=@id",ct,new DbArg("id",id));
 public static void Map(RouteGroupBuilder g)
 {
  g=g.MapGroup("").AddEndpointFilter(async(context,next)=>{foreach(var cap in new[]{"accounting.bas.read","accounting.ledger.read","accounting.gst.read","purchase.input_gst.read"})if(!Access(context.HttpContext).Has(cap))throw new BusinessException("permission_denied","BAS, ledger and both GST reading permissions required.",403);return await next(context);});
  g.MapGet("/accounting/reports/gst-bas",Report).WithMetadata(new Permission("accounting.bas.read"));
  g.MapGet("/accounting/bas-periods",async(int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{var(offset,size)=Page(page,pageSize);return Results.Ok(new{items=(await Read(s,"SELECT p.*,k.state,k.version,k.current_snapshot_id FROM accounting.bas_effective_periods p JOIN accounting.bas_period_controls k ON k.company_id=p.company_id AND k.id=p.id WHERE p.company_id=@company ORDER BY p.from_date,p.id LIMIT @size OFFSET @offset",ct,new DbArg("size",size),new DbArg("offset",offset))).Select(PublicRow)});}).WithMetadata(new Permission("accounting.bas.read"));
  g.MapGet("/accounting/bas-periods/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(PublicRow(await Period(s,id,ct)))).WithMetadata(new Permission("accounting.bas.read"));
  g.MapGet("/accounting/bas-periods/{id:guid}/history",async(Guid id,CompanySession s,CancellationToken ct)=>{await Period(s,id,ct);return Results.Ok(new{methods=(await Read(s,"SELECT * FROM accounting.bas_method_changes WHERE company_id=@company AND period_id=@id ORDER BY version",ct,new DbArg("id",id))).Select(PublicRow),snapshots=(await Read(s,"SELECT id,revision,financial_hash,source_hash,reason,created_at,created_by FROM accounting.bas_snapshots WHERE company_id=@company AND period_id=@id ORDER BY revision",ct,new DbArg("id",id))).Select(PublicRow),events=(await Read(s,"SELECT * FROM accounting.bas_period_events WHERE company_id=@company AND period_id=@id ORDER BY created_at,id",ct,new DbArg("id",id))).Select(PublicRow)});}).WithMetadata(new Permission("accounting.bas.read"));
  g.MapGet("/accounting/bas-snapshots/{id:guid}",async(Guid id,int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{var(offset,size)=Page(page,pageSize);return await Query(s,"SELECT jsonb_build_object('id',s.id,'periodId',s.period_id,'revision',s.revision,'financialHash',s.financial_hash,'sourceHash',s.source_hash,'report',s.report,'totalCount',(SELECT count(*) FROM accounting.bas_snapshot_items WHERE company_id=s.company_id AND snapshot_id=s.id),'items',coalesce((SELECT jsonb_agg(payload ORDER BY source_type,source_id) FROM(SELECT source_type,source_id,payload FROM accounting.bas_snapshot_items WHERE company_id=s.company_id AND snapshot_id=s.id ORDER BY source_type,source_id LIMIT @size OFFSET @offset)x),'[]'::jsonb))::text AS result FROM accounting.bas_snapshots s WHERE s.company_id=@company AND s.id=@id",ct,new DbArg("id",id),new DbArg("size",size),new DbArg("offset",offset));}).WithMetadata(new Permission("accounting.bas.read"));
  g.MapGet("/accounting/bas-classifications/{kind}/{id:guid}",Classification).WithMetadata(new Permission("accounting.bas.read"));
  g.MapPut("/accounting/bas-classifications/{kind}/{id:guid}",Classify).WithMetadata(new Permission("accounting.bas.classify"));
  g.MapPut("/accounting/bas-periods/{id:guid}/method",ChangeMethod).WithMetadata(new Permission("accounting.bas.manage"));
  g.MapPost("/accounting/bas-periods",Create).WithMetadata(new Permission("accounting.bas.manage"));
  foreach(var(action,path,cap)in new[]{("FINALIZED","finalize","accounting.bas.finalize"),("REOPENED","reopen","accounting.bas.reopen"),("LODGED","record-lodgement","accounting.bas.lodged")})g.MapPost("/accounting/bas-periods/{id:guid}/"+path,(Guid id,BasActionInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>Transition(id,action,path,input,h,s,idem,ct)).WithMetadata(new Permission(cap));
 }
 private static async Task<IResult> Report(DateOnly from,DateOnly to,int? page,int? pageSize,string? reportingMethod,string? calculationMethod,CompanySession s,CancellationToken ct)
 {
  Check.That(from.Year>=2&&to>from&&to.DayNumber-from.DayNumber<=366,"to","Use a half-open interval of 1..366 days.");var(offset,size)=Page(page,pageSize);var reporting=Check.OneOf(reportingMethod??"SIMPLER","reportingMethod","SIMPLER","FULL");var calculation=Check.OneOf(calculationMethod??"ACCOUNTS","calculationMethod","ACCOUNTS","WORKSHEET");Check.That(reporting=="FULL"||calculation=="ACCOUNTS","calculationMethod","Worksheet requires FULL reporting.");
  return await Query(s,"WITH report AS MATERIALIZED(SELECT accounting.bas_report(@from,@to,@reporting,@calculation) AS body),sources AS MATERIALIZED(SELECT * FROM accounting.bas_report_sources(@from,@to,@reporting,@calculation)) SELECT(body||jsonb_build_object('page',@page,'pageSize',@size,'totalCount',(SELECT count(*) FROM sources),'items',coalesce((SELECT jsonb_agg(payload ORDER BY source_type,source_id) FROM(SELECT * FROM sources ORDER BY source_type,source_id LIMIT @size OFFSET @offset)x),'[]'::jsonb)))::text AS result FROM report",ct,new DbArg("from",from),new DbArg("to",to),new DbArg("reporting",reporting),new DbArg("calculation",calculation),new DbArg("page",page??1),new DbArg("size",size),new DbArg("offset",offset));
 }
 private static async Task<IResult> Create(BasPeriodInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {
  var reference=Check.Text(input.Reference,"reference",200);Check.OneOf(input.Cadence,"cadence","MONTHLY","QUARTERLY","ANNUAL","CUSTOM");Check.OneOf(input.GstBasis,"gstBasis","CASH","NON_CASH");Check.OneOf(input.ReportingMethod,"reportingMethod","SIMPLER","FULL");Check.OneOf(input.CalculationMethod,"calculationMethod","ACCOUNTS","WORKSHEET");Check.That(input.ReportingMethod=="FULL"||input.CalculationMethod=="ACCOUNTS","calculationMethod","Worksheet requires FULL reporting.");Check.That(input.RegistrationConfirmed&&input.From.Year>=2&&input.To>input.From&&input.To.DayNumber-input.From.DayNumber<=366,"from","Confirm GST registration and supply valid dates.");
  var result=await idem.ExecuteAsync("POST /accounting/bas-periods",h.Request.Headers["Idempotency-Key"].ToString(),input.ReportingMethod=="SIMPLER"?Json(new{Reference=reference,input.From,input.To,input.Cadence,input.GstBasis,input.ReportingMethod,input.RegistrationConfirmed,input.DueOn}):Json(input with{Reference=reference}),async()=>{var id=(Guid)(await One(s,"SELECT accounting.create_bas_period_full(@reference,@from,@to,@cadence,@basis,@method,@registered,@due,@calculation) AS id",ct,new DbArg("reference",reference),new DbArg("from",input.From),new DbArg("to",input.To),new DbArg("cadence",input.Cadence),new DbArg("basis",input.GstBasis),new DbArg("method",input.ReportingMethod),new DbArg("registered",input.RegistrationConfirmed),new DbArg("due",input.DueOn,NpgsqlDbType.Date),new DbArg("calculation",input.CalculationMethod)))["id"]!;await Sql.AuditAsync(s,"accounting.bas_period_created","bas_period",id,h.TraceIdentifier,ct);return ApiJson.Stored(PublicRow(await Period(s,id,ct)),201);},ct);return ApiJson.Result(result);
 }
 private static async Task<IResult> Transition(Guid id,string action,string path,BasActionInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {
  await Period(s,id,ct);var version=Version(h);var reference=Check.Text(input.Reference,"reference",200);var reason=Check.Text(input.Reason,"reason",2000);Check.That(action=="LODGED"||input.LodgedOn is null,"lodgedOn","Lodgement date applies only to recording external lodgement.");
  var result=await idem.ExecuteAsync($"POST /accounting/bas-periods/{id}/{path}",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,version,reference,reason,input.LodgedOn}),async()=>{var snapshot=(Guid)(await One(s,"SELECT accounting.bas_transition(@id,@version,@action,@reference,@reason,@date) AS id",ct,new DbArg("id",id),new DbArg("version",version),new DbArg("action",action),new DbArg("reference",reference),new DbArg("reason",reason),new DbArg("date",input.LodgedOn,NpgsqlDbType.Date)))["id"]!;await Sql.AuditAsync(s,"accounting.bas_"+path.Replace('-','_'),"bas_period",id,h.TraceIdentifier,ct,new{snapshotId=snapshot,reference,reason,input.LodgedOn});return ApiJson.Stored(new{period=PublicRow(await Period(s,id,ct)),snapshotId=snapshot},200);},ct);return ApiJson.Result(result);
 }
 private static string Kind(string kind)=>Check.OneOf(kind,"kind","TAX_CODE","EXPENSE_ACCOUNT","BILL_LINE");
 private static async Task Target(CompanySession s,string kind,Guid id,CancellationToken ct)
 {
  var table=kind switch{"TAX_CODE"=>"accounting.tax_codes","EXPENSE_ACCOUNT"=>"accounting.accounts",_=>"purchase.bill_lines"};await One(s,"SELECT id FROM "+table+" WHERE company_id=@company AND id=@id"+(kind=="EXPENSE_ACCOUNT"?" AND kind='EXPENSE' AND control_kind IS NULL":""),ct,new DbArg("id",id));
 }
 private static async Task<IResult> Classification(string kind,Guid id,CompanySession s,CancellationToken ct)
 {
  kind=Kind(kind);await Target(s,kind,id,ct);return await Query(s,"SELECT jsonb_build_object('targetKind',@kind,'targetId',@id,'revision',coalesce((SELECT revision FROM accounting.bas_latest_classifications WHERE company_id=@company AND target_kind=@kind AND target_id=@id),0),'history',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('input_taxed_percent',x.input_taxed_percent::text) ORDER BY revision) FROM accounting.bas_classifications x WHERE company_id=@company AND target_kind=@kind AND target_id=@id),'[]'::jsonb))::text AS result",ct,new DbArg("kind",kind),new DbArg("id",id));
 }
 private static async Task<IResult> Classify(string kind,Guid id,BasClassificationInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {
  kind=Kind(kind);await Target(s,kind,id,ct);if(!long.TryParse(h.Request.Headers.IfMatch.ToString().Trim('"'),out var version)||version<0)throw new BusinessException("version_required","Current If-Match required; use zero for an unclassified source.",428);var reason=Check.Text(input.Reason,"reason",2000);Check.OneOf(input.SalesClass,"salesClass","AUTO","TAXABLE","EXPORT","OTHER_GST_FREE","INPUT_TAXED","EXCLUDED");Check.OneOf(input.PurchaseClass,"purchaseClass","AUTO","CAPITAL","NON_CAPITAL","EXCLUDED");if(input.InputTaxedPercent is{} percent){Check.Amount(percent,"inputTaxedPercent",4);Check.That(percent>=0&&percent<=100,"inputTaxedPercent","Use a percentage in 0..100.");}
  var result=await idem.ExecuteAsync($"PUT /accounting/bas-classifications/{kind}/{id}",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{kind,id,version,input.SalesClass,input.PurchaseClass,input.InputTaxedPercent,reason}),async()=>{var cid=(Guid)(await One(s,"SELECT accounting.bas_classify(@kind,@id,@version,@sales,@purchase,@percent,@reason)AS id",ct,new DbArg("kind",kind),new DbArg("id",id),new DbArg("version",version),new DbArg("sales",input.SalesClass),new DbArg("purchase",input.PurchaseClass),new DbArg("percent",input.InputTaxedPercent,NpgsqlDbType.Numeric),new DbArg("reason",reason)))["id"]!;await Sql.AuditAsync(s,"accounting.bas_classified","bas_classification",cid,h.TraceIdentifier,ct,new{targetKind=kind,targetId=id,reason});return ApiJson.Stored(new{id=cid,revision=version+1},200);},ct);return ApiJson.Result(result);
 }
 private static async Task<IResult> ChangeMethod(Guid id,BasMethodInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {
  await Period(s,id,ct);var version=Version(h);Check.OneOf(input.ReportingMethod,"reportingMethod","SIMPLER","FULL");Check.OneOf(input.CalculationMethod,"calculationMethod","ACCOUNTS","WORKSHEET");Check.That(input.ReportingMethod=="FULL"||input.CalculationMethod=="ACCOUNTS","calculationMethod","Worksheet requires FULL reporting.");var reason=Check.Text(input.Reason,"reason",2000);
  var result=await idem.ExecuteAsync($"PUT /accounting/bas-periods/{id}/method",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,version,input.ReportingMethod,input.CalculationMethod,reason}),async()=>{await Read(s,"SELECT accounting.bas_change_method(@id,@version,@reporting,@calculation,@reason)",ct,new DbArg("id",id),new DbArg("version",version),new DbArg("reporting",input.ReportingMethod),new DbArg("calculation",input.CalculationMethod),new DbArg("reason",reason));await Sql.AuditAsync(s,"accounting.bas_method_changed","bas_period",id,h.TraceIdentifier,ct,new{input.ReportingMethod,input.CalculationMethod,reason});return ApiJson.Stored(PublicRow(await Period(s,id,ct)),200);},ct);return ApiJson.Result(result);
 }
}
